def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired"):
    return dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status)
INTRO = "<p>These patents trace the blacksmith's and machinist's shop from a leather bellows to the screw-cutting lathe and milling machine &mdash; the 'machine tools that make machine tools'. Use them with the forge, metalworking and workshop chapters of this guide.</p>"
UNPATENTED = ["The <b>anvil, hammer, tongs and side-blast charcoal forge</b> are ancient and free to copy.",
 "The <b>spring-pole lathe</b> and the <b>bow drill</b>, the oldest human-powered machine tools, were never patented."]
PATENTS = [
P("US417632","86/40/c3/fd7055966ac5f7/US417632.pdf","a4/e6/c7/399d67749ee341/US417632-drawings-page-1.png","A","1889-12-17","Frank Christen","Blacksmith's bellows",
  "A cheap, durable blacksmith's bellows made mostly of wood, with the leather reduced to flat, straight-edged pieces so almost none is wasted. Shows the frame, internal partition and air deflector &mdash; a bellows a woodworker can build.","Fig. I side elevation; Fig. IV longitudinal section through the bellows body and partition"),
P("US33479","98/dc/97/8aaf8e49464ec7/US33479.pdf","c3/e6/f4/6ab6a4dc81df23/US33479-drawings-page-1.png","A","1861-10-15","Mathew de la Montanya","Improved blacksmith's portable forge",
  "A portable forge whose cylindrical body is sheet iron riveted air-tight, with a hood that has doors. Shows how a small transportable forge can be made from riveted sheet metal.","Fig. 1 side view; Fig. 3 vertical section showing the air-tight body; Fig. 4 top view"),
P("US510700","91/aa/69/5242a6e5cb92b3/US510700.pdf","6b/0f/9d/3d65728e473ec6/US510700-drawings-page-1.png","B","1893-12-12","S. Frank Myers","Portable bellows-forge",
  "A portable forge with its own bellows, for boilermakers, blacksmiths and shipbuilders, with a tubular air passage through the fire plate to deliver the blast evenly.","Section through bellows, fire pan and air tube"),
P("US654831","48/73/c7/6704d7a6a85aa8/US654831.pdf","42/37/95/c87d80e35ee3b4/US654831-drawings-page-1.png","B","1900-07-31","Charles R. Harper","Portable forge",
  "A light, compact forge pressed from sheet metal, in which the shield also forms part of the fan casing of a crank-driven blower &mdash; the familiar farm and field forge.","Forge body, fan casing and crank drive"),
P("US362721","7d/3f/fc/23217bc76418fb/US362721.pdf","7e/de/e0/aaaf1df9475652/US362721-drawings-page-1.png","B","1887-05-10","William L. Coop","Lathe",
  "A treadle (foot-powered) lathe built for accurate work at a price amateurs could afford, with a slide rest and tailstock that adjust quickly. Turns wood and metal with no engine.","Sheet 1: lathe bed, headstock, treadle drive; later sheets show slide rest and tailstock"),
P("US456560","16/da/13/8cd39884b11fa1/US456560.pdf","8d/d4/57/358000ab0845e6/US456560-drawings-page-1.png","B","1891-07-28","Hiram H. Fuller","Drill-press",
  "Improvements to the drill press, shown in both a floor (column) type and a bench type: frame, spindle and feed that hold the drill square to the work.","Fig. 1 side elevation of the column drill press; Fig. 2 bench drill press"),
P("US536615","01/fe/bd/3eb742ed50761b/US536615.pdf","c0/05/33/044514000b7d31/US536615-drawings-page-1.png","C","1895-04-02","Edward Flather","Screw-cutting lathe",
  "A screw-cutting engine lathe: the carriage is driven by a lead screw geared to the spindle, so the tool cuts accurate threads and fine feeds. Threads, bolts and precise shafts all depend on this machine.","Sheet 1: general view of bed, headstock gearing and carriage"),
P("US636914","95/2a/7b/7d40882bb3685c/US636914.pdf","4b/53/b0/80a0c78f99b5bf/US636914-drawings-page-1.png","C","1899-11-14","Ottmar Mergenthaler","Universal milling-machine",
  "A universal milling machine: a rotating multi-tooth cutter and a table that moves in several directions to cut flat faces, slots and gears. With the lathe, it is how a shop makes precise parts for other machines.","Sheet 1: general elevation; sheets 2&ndash;7 in the PDF show the table feeds and spindle"),
P("US242565","34/5a/3d/51239c2068ed66/US242565.pdf","a1/a7/50/8471da27c9fd4a/US242565-drawings-page-1.png","A","1881-06-07","Fred S. Smedley","Family grindstone",
  "A treadle grindstone for the home. A treadle and rod turn the crank on the stone, leaving both hands free to hold the tool. The whole frame swings on brackets so the stone folds back against the wall when not in use. Build the frame in wood around a salvaged stone (see 2.1 Sharpening).","Fig. 1 in use with the treadle; Fig. 2 swung back against the wall"),
P("US128718","cb/4b/6d/814bdcceb238e2/US128718.pdf","de/dd/56/8967e38e466d63/US128718-drawings-page-1.png","A","1872-07-09","James E. Emerson","Improvement in saw-sets",
  "A saw set that rides on a crosscut saw's removable handle socket, so the teeth can be re-set in the woods. Each tooth is bent over a curved anvil block, and a gauge screw fixes how far it is bent. The patent explains why: pinching timber and filing take the set out of the teeth, and the saw then binds in the kerf (see 2.4 Saw setting and filing).","The single sheet: socket, anvil block and gauge screw with a blade in section"),
P("US280969","06/75/60/50f8a616094d77/US280969.pdf","cb/33/76/761292e867ef1a/US280969-drawings-page-1.png","B","1883-07-10","Albert Standish","Foot-power hammer",
  "An 'Oliver': a treadle trip hammer for the forge, raised by springs and driven down by the smith's foot, with a way to regulate the force of the blow. The bed-plate and hammer are made with integral connecting parts so the frame resists the racking of heavy blows.","Fig. 1 side view of the hammer, springs and treadle linkage"),
P("US16082","b5/5b/30/b6793c1001c0fc/US16082.pdf","pdf:2","C","1856-11-11","Henry Bessemer","Improvement in the manufacture of iron and steel",
  "The Bessemer process: molten crude (pig) iron is run into a closed vessel lined with fire-brick, and air is forced up through it from tuyere pipes. The air burns out the carbon, turning the iron malleable in about thirty minutes. Bessemer gives a worked example of one ton of No. 2 foundry iron blown at about 10 psi through six to twelve tuyeres. This is steelworks scale, shown so you understand where bulk steel comes from (see 4.6).","Sheet 2: the converting vessel, tuyeres and air supply"),
]
